package guardcore

import (
	"fmt"
	"testing"
)

// IP list precedence parity with the reference engine (guard-core Python,
// _utils/access_control.py _check_ip_lists_detail and
// core/checks/helpers.py check_route_ip_access): a configured whitelist
// decides alone and the blacklist is consulted only when no whitelist is
// configured. testdata/ip_list_precedence.json is generated by running the
// reference over every row, never hand-written.

type ipPrecedenceCase struct {
	Whitelist []string `json:"whitelist"`
	Blacklist []string `json:"blacklist"`
	IP        string   `json:"ip"`
	Global    bool     `json:"global"`
	Route     *bool    `json:"route"`
}

func TestIPListPrecedenceMatchesReference(t *testing.T) {
	var cases []ipPrecedenceCase
	loadJSON(t, "ip_list_precedence.json", &cases)
	if len(cases) < 120 {
		t.Fatalf("expected at least 120 reference rows, got %d", len(cases))
	}
	for _, c := range cases {
		if c.IP == "unknown" {
			continue
		}
		label := fmt.Sprintf("wl=%v bl=%v ip=%s", c.Whitelist, c.Blacklist, c.IP)
		engine := clientIPEngine(t, func(cfg *SecurityConfig) {
			cfg.Whitelist = c.Whitelist
			cfg.Blacklist = c.Blacklist
		})
		want := 200
		if !c.Global {
			want = 403
		}
		if got := engineStatus(engine, xffRequest("/api", c.IP, "")); got != want {
			t.Errorf("global %s: status %d, want %d", label, got, want)
		}

		pipeline, _ := newRouteIPTestPipeline(t, routeIPTestRoute, func(rc *RouteConfig) {
			rc.IPWhitelist = c.Whitelist
			rc.IPBlacklist = c.Blacklist
		}, func(cfg *SecurityConfig) {
			cfg.EnableRedis = false
			cfg.EnableRateLimiting = false
		})
		wantRoute := 200
		if c.Route != nil && !*c.Route {
			wantRoute = 403
		}
		got := 200
		if resp := pipeline.Execute(routeIPRequest(t, c.IP, routeIPTestRoute)); resp != nil {
			got = resp.StatusCode
		}
		if got != wantRoute {
			t.Errorf("route %s: status %d, want %d", label, got, wantRoute)
		}
	}
}

type ipRouteGlobalCase struct {
	GlobalWhitelist []string `json:"globalWhitelist"`
	GlobalBlacklist []string `json:"globalBlacklist"`
	RouteWhitelist  []string `json:"routeWhitelist"`
	RouteBlacklist  []string `json:"routeBlacklist"`
	IP              string   `json:"ip"`
	Allowed         bool     `json:"allowed"`
}

// A configured route whitelist skips the global lists for the request (the
// reference skip_ip_lists gate), so a route whitelist match is not relaxed or
// tightened by the global whitelist or blacklist.
func TestRouteAndGlobalIPListsMatchReference(t *testing.T) {
	var cases []ipRouteGlobalCase
	loadJSON(t, "ip_list_route_global.json", &cases)
	if len(cases) < 243 {
		t.Fatalf("expected at least 243 reference rows, got %d", len(cases))
	}
	for _, c := range cases {
		pipeline, _ := newRouteIPTestPipeline(t, routeIPTestRoute, func(rc *RouteConfig) {
			rc.IPWhitelist = c.RouteWhitelist
			rc.IPBlacklist = c.RouteBlacklist
		}, func(cfg *SecurityConfig) {
			cfg.EnableRedis = false
			cfg.EnableRateLimiting = false
			cfg.Whitelist = c.GlobalWhitelist
			cfg.Blacklist = c.GlobalBlacklist
		})
		allowed := pipeline.Execute(routeIPRequest(t, c.IP, routeIPTestRoute)) == nil
		if allowed != c.Allowed {
			t.Errorf("gwl=%v gbl=%v rwl=%v rbl=%v ip=%s: allowed %v, want %v",
				c.GlobalWhitelist, c.GlobalBlacklist, c.RouteWhitelist, c.RouteBlacklist, c.IP, allowed, c.Allowed)
		}
	}
}
